utputData":true},{"typeVersion":2.3,"name":"If custom relation details are needed","position":[-2096,16],"id":"a7c0855f-177e-4660-bc03-ef618a4db5a4","type":"n8n-nodes-base.if","parameters":{"options":{},"conditions":{"combinator":"and","options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"leftValue":"={{ $(''Get Input data'').first().json.conceptUris }}","rightValue":"","id":"17e042f9-d8bf-42ce-a73c-143d88e055aa","operator":{"singleValue":true,"type":"array","operation":"notEmpty"}},{"leftValue":"={{ $(''Get Input data'').first().json.customConceptProperties }}","rightValue":"","id":"880bcb74-8dda-481d-a89a-a7a2ab2720f2","operator":{"singleValue":true,"type":"array","operation":"notEmpty"}}]}}},{"typeVersion":2,"name":"Custom relation SPARQL query","position":[-1200,-64],"id":"61da86b0-18bf-4cb1-9502-67d56141965c","type":"n8n-nodes-base.code","parameters":{"jsCode":"const query = `PREFIX ppt:<http://schema.semantic-web.at/ppt/>\nSELECT DISTINCT ?relation ?label ?isRelation\nWHERE {\n    { ?ontology ppt:containsDirectedProperty|ppt:containsPropertyWithInverse|ppt:containsSymmetricProperty ?relation .\n      ?relation rdfs:label ?label }\n    UNION { ?relation a owl:DatatypeProperty .\n            ?relation rdfs:label ?label }\n  BIND(EXISTS{?relation a owl:ObjectProperty} AS ?isRelation)\n}`;\n\nreturn {\n  query\n};"}},{"typeVersion":2,"name":"Transform SPARQL bindings into object","position":[-784,-64],"id":"d1b69fda-1627-43ce-a02f-7692c04d31d8","type":"n8n-nodes-base.code","parameters":{"jsCode":"let relationDetails = {};\n\nfor (const sparqlBinding of $input.first().json.results.bindings) {\n  relationDetails[sparqlBinding.relation.value] = {\n    \"label\": sparqlBinding.label.value,\n    \"isRelation\": (sparqlBinding.isRelation.value === \"true\")\n  };\n}\n\nreturn relationDetails;"}},{"typeVersion":1,"name":"Load custom relation details from cache","position":[-1680,-160],"id":"8a41a1fe-7317-492d-b890-f684735ed