ion);\n\nconst structuredOutputParserJsonSchema = {\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"type\": \"object\",\n  \"properties\": {\n    \"chatInput\": {\n      \"type\": \"string\"\n    },\n    \"language\": {\n      \"type\": \"string\"\n    },\n    \"impersonationRole\": {\n      \"type\": \"string\"\n    },\n    \"userPersona\": {\n      \"type\": \"string\"\n    },\n    \"targetAction\": {\n      \"type\": \"string\"\n    },\n    \"topics\": {\n      \"type\": \"string\"\n    }\n  },\n  \"required\": [\n    \"chatInput\",\n    \"language\"\n  ],\n  \"additionalProperties\": false\n}\n\nreturn { \"systemMessageTemplate\" : systemMessageTemplate,\n         \"structuredOutputParserJsonSchema\" : structuredOutputParserJsonSchema\n       }\n"}}]', '{"prepare input data":{"main":[[{"node":"Call ''Configuration (sub-workflow)''","index":0,"type":"main"}]]},"Prepare output data":{"main":[[{"node":"Insert success data for parallel sync","index":0,"type":"main"}]]},"Call ''Configuration (sub-workflow)''":{"main":[[{"node":"Prepare data for LLM call","index":0,"type":"main"}]]},"Prepare error data":{"main":[[{"node":"Insert error data for parallel sync","index":0,"type":"main"}]]},"LLM call":{"main":[[{"node":"Prepare output data","index":0,"type":"main"}],[{"node":"Prepare error data","index":0,"type":"main"}]]},"Webhook":{"main":[[{"node":"prepare input data","index":0,"type":"main"}]]},"Prepare data for LLM call":{"main":[[{"node":"LLM call","index":0,"type":"main"}]]}}', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:56.482+01', '{"callerPolicy":"workflowsFromSameOwner","errorWorkflow":"Q07I0sRZf6eCtuuF","executionOrder":"v1"}', NULL, '{}', '8eb93933-0ee4-4022-a7c4-a9e764c70cf9', 1, 'EbNZ8ZIahgC1CPjZ', '{"instanceId":"982a83c4fa14b8860ea8391b8f766ad449d7431aac64126d0b9fc936877b58be"}', NULL, false, 3, NULL);
