values('Step - PoolParty Concept Enricher - Sync', true, '[{"typeVersion":1,"name":"Sticky Note","position":[-896,48],"id":"7f45e886-4a44-4231-b685-6c75d366c9f6","type":"n8n-nodes-base.stickyNote","parameters":{"width":784,"content":"## What to use this workflow for\n- Final answer injection\n- Retrieval\nwe should provide both options, with easy activation and deactivation ---------> see the next sticky note","height":128}},{"typeVersion":1,"name":"Sticky Note1","position":[0,0],"id":"c684fada-573b-4533-b9ae-0cf8d4a0b287","type":"n8n-nodes-base.stickyNote","parameters":{"width":752,"content":"🧭 Summary of What to Use Where\n────────────────────────────────────────\n*Use Case:*          |  |  |         *Output Field:*        |  |  |       *What to Keep:*\n────────────────────────────────────────\n**Final Answer (LLM)**         |  |  |   llmContextText            |  |  |  Full explanations\n**Query Rewriting Prompt**      |  |  |   queryRewritingContext     |  |  |  Primary terms, synonyms, broader context\n**Dense Vector Retrieval**      |  |  |   retrievalQueries          |  |  |  Multiple query variations + definitions\n**Sparse / Keyword Retrieval**  |  |  |   keywords / keywordsText   |  |  |  Just the labels (no definitions)\n**Hybrid Retrieval**           |  |  |  queryExpansion object      |  |  | All terms organized by type\n────────────────────────────────────────\n\n🧩 Recommended Workflow\n• Use retrievalQueries to generate 3–7 vector searches  \n• Use keywords for BM25 / keyword-based search  \n• Combine results (hybrid retrieval)  \n• Use llmContextText when injecting context into final answer\n\n","height":400}},{"typeVersion":2,"name":"URI extraction and batch","position":[128,480],"id":"2b4f5004-e7dd-4c9d-9418-ed342668ff8e","type":"n8n-nodes-base.code","parameters":{"jsCode":"// SIMPLIFIED: Extract URIs and create batch request directly\nconst items = $input.all();\nconst output = [];\n\nfor (const item of items) {\n  try {\n    const response = item.json;\n    const projectId = response.projectId || response.project || $(''Configuration'').first().json.poolPartyProjectId;\n    \n    // Track URIs with their types (single Map, no Sets)\n    const uriTypeMap = new Map();\n    \n    if (response.concepts && Array.isArray(response.concepts)) {\n      response.concepts.forEach(concept => {\n        if (concept.uri) {\n          if (!uriTypeMap.has(concept.uri)) uriTypeMap.set(concept.uri, []);\n          if (!uriTypeMap.get(concept.uri).includes(''seed'')) {\n            uriTypeMap.get(concept.uri).push(''seed'');\n          }\n        }\n      });\n    }\n    \n    const urisArray = Array.from(uriTypeMap.keys());\n    \n    // DIRECT OUTPUT: Single batched item, no splitting\n    output.push({\n      json: {\n        conceptUris: urisArray,\n        projectId: projectId,\n        originalExtractionResponse: response,\n        batchSize: urisArray.length,\n        timestamp: new Date().toISOString()\n      }\n    });\n    \n  } catch (error) {\n    output.push({\n      json: {\n        error: true,\n        errorMessage: error.message,\n        timestamp: new Date().toISOString()\n      }\n    });\n  }\n}\n\nreturn output;"},"alwaysOutputData":true},{"typeVersion":4.2,"credentials":{"httpBasicAuth":{"id":"emxYnbbzTTT6DtWc","name":"PoolParty Credentials"}},"name":"Extract concepts terms from ChatMessage","position":[-144,480],"id":"3f701e9e-c55a-4e55-ac7b-10e11a152e98","type":"n8n-nodes-base.httpRequest","parameters":{"bodyParameters":{"parameters":[{"name":"projectId","value":"={{ $json.poolpartyConfig.formData.projectId }}"},{"name":"text","value":"={{ $json.poolpartyConfig.formData.text }}"},{"name":"language","value":"={{ $json.poolpartyConfig.formData.language }}"},{"name":"numberOfConcepts","value":"={{ $json.poolpartyConfig.formData.numberOfConcepts }}"},{"name":"showMatchingDetails","value":"={{ $json.poolpartyConfig.formData.showMatchingDetails }}"},{"name":"displayText","value":"={{ $json.poolpartyConfig.formData.displayText }}"},{"name":"filterNestedConcepts","value":"={{ $json.poolpartyConfig.formData.filterNestedConcepts }}"},{"name":"useRelatedConcepts","value":"={{ $json.poolpartyConfig.formData.useRelatedConcepts }}"},{"name":"showMatchingPosition","value":"true"},{"name":"conceptMinimumScore","value":"={{ $json.poolpartyConfig.formData.conceptMinimumScore }}"},{"name":"numberOfTerms","value":"0"}]},"method":"POST","sendBody":true,"options":{"response":{"response":{}}},"genericAuthType":"httpBasicAuth","contentType":"form-urlencoded","url":"={{ $json.poolpartyConfig.apiUrl }}","authentication":"genericCredentialType"}},{"typeVersion":2,"name":"Build extraction request","position":[-384,480],"id":"929373c2-31f0-4788-84cb-17a2118f6e51","type":"n8n-nodes-base.code","parameters":{"jsCode":"// Build ENHANCED PoolParty API request with optimal parameters\nconst items = $(''When executed by another workflow'').all();\nconst output = [];\n\nconst POOLPARTY_CONFIG = {\n  serverUrl: $input.first().json.poolPartyServerUrl,\n  projectId: $input.first().json.poolPartyProjectId,\n  username: ''{{POOLPARTY_USERNAME}}'',\n  password: ''{{POOLPARTY_PASSWORD}}''\n};\n\nfor (const item of items) {\n  \n  const text = item.json.chatInput;\n  const language = item.json.language || ''en'';\n  \n  // ENHANCED parameters based on API research\n  const formData = {\n    projectId: POOLPARTY_CONFIG.projectId,\n    text: text,\n    language: language,\n    numberOfConcepts: ''15'',  // Increased for better coverage\n    conceptMinimumScore: ''20'', // Concept score threshold (0 to 100)\n    \n    // CRITICAL: Get full hierarchies in ONE call\n    useTransitiveBroaderConcepts: ''true'',\n    useTransitiveBroaderTopConcepts: ''true'',\n    \n    // Quality improvements\n    useRelatedConcepts: ''true'',\n    filterNestedConcepts: ''true'',\n    showMatchingDetails: ''true'',\n    \n    // Advanced scoring\n    corpusScoring: ''true'',  // Better relevance for RAG queries\n    disambiguate: ''true'',   // Resolve ambiguous terms\n    \n    // Optional: If you have a corpus configured\n    // shadowConceptCorpusId: ''your-corpus-id'',  // Discovers implicit concepts\n    \n    displayText: ''false''\n  };\n  \n  output.push({\n    json: {\n      ...item.json,\n      poolpartyConfig: {\n        apiUrl: `${POOLPARTY_CONFIG.serverUrl}/extractor/api/extract`,\n        formData: formData\n      }\n    }\n  });\n}\n\nreturn output;"},"alwaysOutputData":true},{"typeVersion":1.1,"maxTries":2,"onError":"continueRegularOutput","name":"When executed by another workflow","position":[-880,480],"id":"8ec3ad6d-4004-4473-9e94-fe9f1d9599d6","type":"n8n-nodes-base.executeWorkflowTrigger","retryOnFail":true,"parameters":{"workflowInputs":{"values":[{"name":"chatInput"},{"name":"language"},{"name":"targetAction"},{"name":"topics"},{"name":"jwtToken"}]}},"alwaysOutputData":true},{"typeVersion":1.3,"name":"Configuration","position":[-640,480],"id":"cd7beaba-1893-4d68-ae85-f699b11d1a83","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/workflow/HJcJwMTssnY79HWw","__rl":true,"cachedResultName":"Configuration (sub-workflow)","value":"HJcJwMTssnY79HWw"}}},{"typeVersion":4.2,"name":"Fetch concept details","position":[400,480],"id":"3e25ac7f-1a16-40ff-8f69-912ce6543e91","type":"n8n-nodes-base.httpRequest","parameters":{"bodyParameters":{"parameters":[{"name":"conceptUris","value":"={{ $json.conceptUris }}"},{"name":"originalExtractionResponse","value":"={{ $json.originalExtractionResponse }}"},{"name":"batchSize","value":"={{ $json.batchSize }}"}]},"method":"POST","headerParameters":{"parameters":[{"name":"Authentication","value":"=Bearer {{ $(''When executed by another workflow'').item.json.jwtToken }}"}]},"sendBody":true,"options":{},"sendHeaders":true,"url":"={{ $(''Configuration'').item.json.internalN8nUrl }}/webhook/fetch-concept-details"}}]', '{"Build extraction request":{"main":[[{"node":"Extract concepts terms from ChatMessage","index":0,"type":"main"}]]},"Configuration":{"main":[[{"node":"Build extraction request","index":0,"type":"main"}]]},"When executed by another workflow":{"main":[[{"node":"Configuration","index":0,"type":"main"}]]},"Extract concepts terms from ChatMessage":{"main":[[{"node":"URI extraction and batch","index":0,"type":"main"}]]},"URI extraction and batch":{"main":[[{"node":"Fetch concept details","index":0,"type":"main"}]]}}', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:56.482+01', '{"executionOrder":"v1"}', NULL, '{}', '28aad05b-608c-4608-89e3-724fa406ad36', 0, 'CxgHGMN2a1fwwEmt', '{"instanceId":"982a83c4fa14b8860ea8391b8f766ad449d7431aac64126d0b9fc936877b58be"}', NULL, false, 3, NULL);
insert into public.workflow_entity("name", "active", "nodes", "connections", "createdAt", "updatedAt", "settings", "staticData", "pinData", "versionId", "triggerCount", "id", "meta", "parentFolderId", "isArchived", "versionCounter", "description")
values('Step - PoolParty Expansion - Async', true, '[{"typeVersion":1,"name":"Sticky Note1","position":[-1024,-304],"id":"3ade6fc3-3956-4ae6-91c5-9044335b4b08","type":"n8n-nodes-base.stickyNote","parameters":{"width":544,"content":"# PoolParty Concept Expansion\n## Overview\nThis sub-workflow performs concept expansion using PoolParty. It takes user chat input (triggered by another workflow), extracts relevant concepts, and then expands these concepts hierarchically to provide a comprehensive semantic context for downstream processing, such as, semantic search, or LLM context enhancement.\n\n","height":240}},{"typeVersion":1,"name":"Sticky Note2","position":[224,-832],"id":"2d4514fb-ec6d-4a9d-8604-3543ef592c56","type":"n8n-nodes-base.stickyNote","parameters":{"color":4,"width":320,"content":"## Input Parameters\nThe workflow accepts the following inputs when invoked:\n\n**`chatInput`**\n- **Type:** String\n- **Required:** Yes\n- **Description:** The user''s natural language query or message\n\n**`language`**\n- **Type:** String\n- **Required:** Optional\n- **Description:** Language code (defaults to ''en'')\n\n**`targetAction`**\n- **Type:** String\n- **Required:** Optional\n- **Description:** Reserved for future use\n\n**`topics`**\n- **Type:** Any\n- **Required:** Optional\n- **Description:** Reserved for future use\n","height":720}},{"typeVersion":1,"name":"Sticky Note3","position":[1712,-624],"id":"833aff11-4086-4194-8cfb-2018ebb97315","type":"n8n-nodes-base.stickyNote","parameters":{"color":6,"width":320,"content":"## Output Structure\n\nThe workflow returns a structured JSON object containing:\n\n- **Seed Concepts**: concepts extracted from the initial input\n- **Expanded Concepts**: Hierarchically organized expanded seed concepts\n- **Retrieval URIs**: Concept URIs grouped by relevance (exact, primary, secondary, tertiary)\n- **LLM-Friendly Format**: Structured data optimized for language model context\n\n","height":576}},{"typeVersion":1,"name":"Sticky Note4","position":[208,-80],"id":"bf0ec3b3-aa90-4ddd-b3c6-34551a12b7ad","type":"n8n-nodes-base.stickyNote","parameters":{"color":5,"width":368,"content":"#### Configuration required","height":240}},{"typeVersion":1,"name":"Sticky Note5","position":[1296,-288],"id":"ff8a4f83-5b85-4220-8a32-0b4176d21ffb","type":"n8n-nodes-base.stickyNote","parameters":{"color":5,"width":384,"content":"#### Configuration required","height":240}},{"typeVersion":2.1,"webhookId":"88bd9258-8e2b-42d6-8284-9bb154bd0d5f","name":"Webhook","position":[-560,0],"id":"fd2df738-676c-4c53-b4fa-1b3b44b281d3","type":"n8n-nodes-base.webhook","parameters":{"path":"internal/concept-expansion","options":{},"httpMethod":"POST"}},{"typeVersion":2,"name":"prepare input data","position":[-336,0],"id":"16f58ac2-fb67-4fed-b09e-66501727e86d","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {\n  \"targetAction\":  null,\n  \"topics\": null,\n  \"chatInput\":  $input.first().json.body.chatInput,\n  \"language\": $input.first().json.body.language,\n  \"executionId\" : $input.first().json.body.executionId,\n  \"stepTag\": \"concept-expansion\"\n}"}},{"typeVersion":1,"name":"Sticky Note","position":[-400,-208],"id":"dd744463-ed0c-4c46-bc88-0a89ca320cb7","type":"n8n-nodes-base.stickyNote","parameters":{"color":6,"width":224,"content":"## Please keep the name of the node intact - required for error async processing","height":336}},{"typeVersion":1,"name":"Insert success data for parallel sync","position":[2352,0],"id":"1d96a15c-72a0-46ea-bf85-f4bc5081a31d","type":"n8n-nodes-base.dataTable","parameters":{"columns":{"schema":[{"defaultMatch":false,"removed":false,"displayName":"executionId","display":true,"readOnly":false,"id":"executionId","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"step","display":true,"readOnly":false,"id":"step","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"type","display":true,"readOnly":false,"id":"type","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"value","display":true,"readOnly":false,"id":"value","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"isProcessed","display":true,"readOnly":false,"id":"isProcessed","type":"boolean","required":false}],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":false,"mappingMode":"defineBelow","value":{"executionId":"={{ $(''prepare input data'').first().json.executionId }}","isProcessed":false,"step":"={{ $(''prepare input data'').first().json.stepTag}}","type":"success","value":"={{ JSON.stringify($json) }}"}},"dataTableId":{"mode":"list","cachedResultUrl":"/projects/xFJBxfuIaoygFpGG/datatables/MKjbck0nu6xOvBsi","__rl":true,"cachedResultName":"PARALLEL_SYNC_DATA","value":"VQol99zJXwRSl6hz"},"options":{}}},{"typeVersion":1,"name":"Insert error data for parallel sync","position":[1584,144],"id":"ce8e8303-0971-4f6d-a0b7-828b5459072c","type":"n8n-nodes-base.dataTable","parameters":{"columns":{"schema":[{"defaultMatch":false,"removed":false,"displayName":"executionId","display":true,"readOnly":false,"id":"executionId","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"step","display":true,"readOnly":false,"id":"step","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"type","display":true,"readOnly":false,"id":"type","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"value","display":true,"readOnly":false,"id":"value","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"isProcessed","display":true,"readOnly":false,"id":"isProcessed","type":"boolean","required":false}],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":false,"mappingMode":"defineBelow","value":{"executionId":"={{ $(''prepare input data'').first().json.executionId }}","isProcessed":false,"step":"={{ $(''prepare input data'').first().json.stepTag}}","type":"error","value":"={{ JSON.stringify($json) }}"}},"dataTableId":{"mode":"list","cachedResultUrl":"/projects/xFJBxfuIaoygFpGG/datatables/MKjbck0nu6xOvBsi","__rl":true,"cachedResultName":"PARALLEL_SYNC_DATA","value":"VQol99zJXwRSl6hz"},"options":{}}},{"typeVersion":1.3,"name":"Call ''Configuration (sub-workflow)''","position":[-48,0],"id":"3b6d793d-1d9b-4215-8fca-3028362f28a7","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/workflow/HJcJwMTssnY79HWw","__rl":true,"cachedResultName":"Configuration (sub-workflow)","value":"HJcJwMTssnY79HWw"}}},{"typeVersion":2,"name":"Build extraction request","position":[224,0],"id":"d1b9e714-99e1-4807-a452-bcc0f2866767","type":"n8n-nodes-base.code","parameters":{"jsCode":"// Build PoolParty API request with optimal parameters\nconst items =[];\nitems.push($(''Webhook'').first().json.body);\n\nconst output = [];\n\nconst PROJECT_ID = $(''Call \\''Configuration (sub-workflow)\\'''').first().json.poolPartyProjectId; \n\nfor (const item of items) {\n \n  const text = item.chatInput;\n  const language = item.language || ''en'';\n  \n  // parameters based on API research\n  const formData = {\n    projectId: PROJECT_ID,\n    text: text,\n    language: language,\n    numberOfConcepts: ''5'',  // Increased for better coverage\n    \n    //  Get full hierarchies in ONE call\n    useTransitiveBroaderConcepts: ''true'',\n    useTransitiveBroaderTopConcepts: ''true'',\n    \n    // Quality improvements\n    useRelatedConcepts: ''true'',\n    filterNestedConcepts: ''true'',\n    showMatchingDetails: ''true'',\n    \n    // Advanced scoring\n    corpusScoring: ''true'',  // Better relevance for RAG queries\n    disambiguate: ''true'',   // Resolve ambiguous terms\n    \n    displayText: ''false''\n  };\n  \n  output.push({\n    json: {\n      ...item.json,\n      formData: formData\n    }\n  });\n}\n\nreturn output;"}},{"typeVersion":4.2,"onError":"continueErrorOutput","credentials":{"httpBasicAuth":{"id":"emxYnbbzTTT6DtWc","name":"PoolParty Credentials"}},"name":"Extract concepts from user query","position":[448,0],"id":"130e93a0-b758-46c1-b6a8-708549cb6e33","type":"n8n-nodes-base.httpRequest","parameters":{"bodyParameters":{"parameters":[{"name":"projectId","value":"={{ $json.formData.projectId }}"},{"name":"text","value":"={{ $json.formData.text }}"},{"name":"language","value":"={{ $json.formData.language }}"},{"name":"numberOfConcepts","value":"={{ $json.formData.numberOfConcepts }}"},{"name":"showMatchingDetails","value":"={{ $json.formData.showMatchingDetails }}"},{"name":"filterNestedConcepts","value":"={{ $json.formData.filterNestedConcepts }}"},{"name":"useRelatedConcepts","value":"={{ $json.formData.useRelatedConcepts }}"},{"name":"disambiguate","value":"={{ $json.formData.disambiguate }}"},{"name":"displayText","value":"={{ $json.formData.displayText }}"},{"name":"useTransitiveBroaderConcepts","value":"={{ $json.formData.useTransitiveBroaderConcepts }}"},{"name":"useTransitiveBroaderTopConcepts","value":"={{ $json.formData.useTransitiveBroaderTopConcepts }}"}]},"method":"POST","sendBody":true,"options":{"response":{"response":{}}},"genericAuthType":"httpBasicAuth","contentType":"form-urlencoded","url":"={{ $(''Call \\''Configuration (sub-workflow)\\'''').first().json.poolPartyServerUrl }}/extractor/api/extract","authentication":"genericCredentialType"}},{"typeVersion":2,"name":"Extract seeds to expand","position":[688,0],"id":"1f989ec6-69f9-437c-b68c-3afcb5dd6230","type":"n8n-nodes-base.code","parameters":{"jsCode":"// Extract seed concept URIs from extraction response\n// Here we take ALL extracted concepts as seed concepts for further expansion\n// All concepts are given a score of 100 for expansion purposes\nconst items = $input.all();\nconst output = [];\n\nfor (const item of items) {\n  try {\n    const extractionResponse = item.json;\n    \n    // Collect seed concept URIs (all concepts with score 100)\n    const seedConcepts = new Map();\n    const seedMetadata = new Map();\n    \n    if (extractionResponse.concepts && Array.isArray(extractionResponse.concepts)) {\n      extractionResponse.concepts.forEach(concept => {\n        // Take ALL extracted concepts and assign score 100 for expansion\n        if (concept.uri) {\n          seedConcepts.set(concept.uri, {score: 100});  // Force score to 100\n          \n          seedMetadata.set(concept.uri, {\n            uri: concept.uri,\n            label: concept.prefLabels?.en || Object.values(concept.prefLabels || {})[0],\n            altLabels: concept.altLabels?.en || [],\n            score: 100,  // Force score to 100\n            originalScore: concept.score,  // Keep original score for reference\n            matchedAs: concept.matchingLabels?.map(m => m.label) || []\n          });\n        }\n      });\n    }\n    \n    console.log(''✓ Extracted seed concepts:'', {\n      totalExtracted: extractionResponse.concepts?.length || 0,\n      seedsForExpansion: seedConcepts.size\n    });\n    \n    // Validation - need at least one concept to expand\n    if (seedConcepts.size === 0) {\n      console.warn(''⚠️  No concepts found for expansion'');\n      throw new Error(''No concepts extracted from text. Cannot perform expansion.'');\n    }\n    \n    output.push({\n      json: {\n        // Original config (from extractionConfig parent)\n        text: extractionResponse.text || extractionResponse.extractionConfig?.formData?.text,\n        language: extractionResponse.language || extractionResponse.extractionConfig?.formData?.language,\n        projectId: extractionResponse.projectId || extractionResponse.extractionConfig?.formData?.projectId,\n        expansionStrategy: extractionResponse.expansionStrategy,\n        maxDepth: extractionResponse.maxDepth,\n        maxResults: extractionResponse.maxResults,\n        \n        // Extracted seeds (all with score 100)\n        seedConcepts: Object.fromEntries(seedConcepts),\n        seedMetadata: Object.fromEntries(seedMetadata),\n        \n        // Full extraction response for reference\n        originalExtraction: extractionResponse,\n        \n        timestamp: new Date().toISOString()\n      }\n    });\n    \n  } catch (error) {\n    console.error(''❌ Seed extraction error:'', error.message);\n    output.push({\n      json: {\n        error: true,\n        errorMessage: error.message,\n        timestamp: new Date().toISOString()\n      }\n    });\n  }\n}\n\nreturn output;"},"alwaysOutputData":true},{"typeVersion":2.2,"name":"If concepts are found","position":[912,0],"id":"49806c69-6cbf-4513-a6de-68bc0497362c","type":"n8n-nodes-base.if","parameters":{"options":{},"conditions":{"combinator":"and","options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"leftValue":"={{ $input.first().json.error }}","rightValue":"","id":"d2ee2317-b1d4-424f-9cdc-b00abe860383","operator":{"singleValue":true,"type":"boolean","operation":"notExists"}}]}}},{"typeVersion":2,"name":"Prepare JSON list","position":[1104,-208],"id":"a2837cd8-0fe8-41ee-ae87-7748f27cb25e","type":"n8n-nodes-base.code","parameters":{"jsCode":"var res = []\nfor(const concept in $(''Extract seeds to expand'').first().json.seedConcepts){ \n  res.push({\n    \"uri\": concept,\n    \"score\":$(''Extract seeds to expand'').first().json.seedConcepts[concept].score\n  })\n}\n\nreturn res;"},"alwaysOutputData":true},{"typeVersion":2,"name":"Build expansion request","position":[1328,-208],"id":"348d2d0d-08fe-4d8d-8029-2696a1bc826a","type":"n8n-nodes-base.code","parameters":{"jsCode":"var conceptList =  $input.all();\nvar finalList = [];\n\nfor(var concept in conceptList){\n  finalList.push({\n    \"uri\": conceptList[concept].json.uri,\n    \"score\": conceptList[concept].json.score\n  });\n}\n\nreturn [{\n  \"concepts\": finalList,\n  \"expansionQuery\": \"prefix skos:<http://www.w3.org/2004/02/skos/core#>\\nselect ?uri ?label ?finalScore\\nwhere {\\n  ?uri skos:prefLabel ?label . FILTER ( lang(?label) = ''en'' ) {\\n    select ?uri (MAX(?expansionScore) as ?finalScore) where { VALUES (?x ?inScore)\\n      { <inputConcepts> }\\n      { BIND(?x AS ?uri) BIND(STRDT(''1.00'',xsd:float) AS ?distScore) }\\n      UNION { ?x skos:narrower ?y . BIND(STRDT(''0.8'',xsd:float) AS ?distScore) }\\n      UNION { ?x skos:narrower/skos:narrower ?y . BIND(STRDT(''0.4'',xsd:float) AS ?distScore) }\\n      UNION { ?x skos:broader/skos:narrower ?y . filter(!sameTerm(?x,?y)) BIND(STRDT(''0.2'',xsd:float) AS ?distScore) }\\n      BIND(IF(BOUND(?y), ?y, ?x) AS ?uri) .\\n      BIND(?distScore * ?inScore AS ?expansionScore) . \\n    }\\n    GROUP BY ?uri order by desc(?finalScore)\\n  }\\n}\\nlimit <numberOfConcepts>\",\n  \"language\": \"en\",\n  \"maxNumberOfConcepts\": 50,\n  \"properties\": [\n    \"skos:prefLabel\",\n    \"skos:altLabel\",\n    \"skos:definition\",\n    \"skos:broader\",\n    \"skos:narrower\",\n    \"skos:related\"\n  ]\n}]"},"alwaysOutputData":true},{"typeVersion":2,"name":"Prepare error data","position":[1344,144],"id":"e3259fe8-bd56-47da-9a1a-40a3091d4bc8","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {\n  \"executionId\": $executionId\n}"}},{"typeVersion":4.2,"onError":"continueErrorOutput","credentials":{"httpBasicAuth":{"id":"emxYnbbzTTT6DtWc","name":"PoolParty Credentials"}},"name":"Expand concepts from user query","position":[1552,-208],"id":"434a921f-6063-433a-a2df-afd6a5b5b9b3","type":"n8n-nodes-base.httpRequest","parameters":{"method":"POST","specifyBody":"json","headerParameters":{"parameters":[{"name":"Accept","value":"application/json"}]},"sendBody":true,"options":{"response":{}},"jsonBody":"={{ JSON.stringify($json) }}","genericAuthType":"httpBasicAuth","sendHeaders":true,"url":"={{ $(''Call \\''Configuration (sub-workflow)\\'''').first().json.poolPartyServerUrl }}/PoolParty/api/tagging/{{ $(''Call \\''Configuration (sub-workflow)\\'''').first().json.poolPartyProjectId }}/expand","authentication":"genericCredentialType"}},{"typeVersion":2,"name":"Structure expansion results","position":[1776,-208],"id":"bbf69547-c8ef-4c24-8c87-592e414ad729","type":"n8n-nodes-base.code","parameters":{"jsCode":"// Parse and structure expansion results for LLM/retrieval\nconst items = $input.all();\n\n// The response is an ARRAY with one object inside\nconst responseArray = $input.first().json;\nconst expansionData = Array.isArray(responseArray) ? responseArray[0] : responseArray;\n\nconsole.log(''✓ Expansion message:'', expansionData.message);\n\n// Safely extract expanded concepts\nconst expandedConcepts = expansionData?.expandedConcepts || [];\nconsole.log(''✓ Total concepts expanded:'', expandedConcepts.length);\n\n// Validate we have data\nif (!expandedConcepts || expandedConcepts.length === 0) {\n  console.warn(''⚠️ No expanded concepts found in response'');\n  return {\n    json: {\n      error: false,\n      warning: ''No concepts expanded'',\n      message: expansionData?.message || ''No message'',\n      query: $(''prepare input data'').first().json.chatInput\n    }\n  };\n}\n\n// Get seed concepts from previous node\nconst seedData = $(''Expand concepts from user query'').first().json;\nconst query = $(''prepare input data'').first().json.chatInput;\n\n// Categorize concepts by score\nconst byScore = {\n  seeds: expandedConcepts.filter(c => c.score === 100),        // Original extracted concepts\n  primary: expandedConcepts.filter(c => c.score === 80),       // 1-level narrower\n  secondary: expandedConcepts.filter(c => c.score === 40),     // 2-level narrower\n  related: expandedConcepts.filter(c => c.score === 20)        // Siblings/related\n};\n\nconsole.log(''📊 Concept distribution:'', {\n  seeds: byScore.seeds.length,\n  primary: byScore.primary.length,\n  secondary: byScore.secondary.length,\n  related: byScore.related.length\n});\n\n// ========================================\n// 1. RETRIEVAL-OPTIMIZED STRUCTURE\n// ========================================\nconst retrievalIndex = {\n  // Tiered URIs for weighted retrieval\n  tiers: {\n    tier1_seeds: byScore.seeds.map(c => ({\n      uri: c.jsonConcept?.uri,\n      label: c.jsonConcept?.prefLabel,\n      weight: 1.0,\n      altLabels: c.jsonConcept?.altLabels || []\n    })),\n    \n    tier2_primary: byScore.primary.map(c => ({\n      uri: c.jsonConcept?.uri,\n      label: c.jsonConcept?.prefLabel,\n      weight: 0.8,\n      altLabels: c.jsonConcept?.altLabels || []\n    })),\n    \n    tier3_secondary: byScore.secondary.map(c => ({\n      uri: c.jsonConcept?.uri,\n      label: c.jsonConcept?.prefLabel,\n      weight: 0.5,\n      altLabels: c.jsonConcept?.altLabels || []\n    })),\n    \n    tier4_related: byScore.related.map(c => ({\n      uri: c.jsonConcept?.uri,\n      label: c.jsonConcept?.prefLabel,\n      weight: 0.3,\n      altLabels: c.jsonConcept?.altLabels || []\n    }))\n  },\n  \n  // Flat lists for easy filtering\n  allURIs: expandedConcepts.map(c => c.jsonConcept?.uri).filter(uri => uri),\n  seedURIs: byScore.seeds.map(c => c.jsonConcept?.uri).filter(uri => uri),\n  expandedURIs: [...byScore.primary, ...byScore.secondary, ...byScore.related]\n    .map(c => c.jsonConcept?.uri)\n    .filter(uri => uri),\n  \n  // Query expansion terms (for full-text search)\n  queryExpansionTerms: {\n    primary: [\n      ...new Set([\n        ...byScore.seeds.flatMap(c => [c.jsonConcept?.prefLabel, ...(c.jsonConcept?.altLabels || [])]),\n        ...byScore.primary.flatMap(c => [c.jsonConcept?.prefLabel, ...(c.jsonConcept?.altLabels || [])])\n      ].filter(Boolean))\n    ].slice(0, 30),\n    \n    secondary: [\n      ...new Set([\n        ...byScore.secondary.flatMap(c => [c.jsonConcept?.prefLabel, ...(c.jsonConcept?.altLabels || [])])\n      ].filter(Boolean))\n    ].slice(0, 20)\n  },\n  \n  // Relationship graph for traversal\n  relationships: expandedConcepts.map(c => ({\n    uri: c.jsonConcept?.uri,\n    broaders: c.jsonConcept?.broaders || [],\n    narrowers: c.jsonConcept?.narrowers || [],\n    related: c.jsonConcept?.relateds || []\n  }))\n};\n\n// ========================================\n// 2. LLM CONTEXT STRUCTURE\n// ========================================\nconst llmContext = {\n  // Pre-formatted context string ready for injection\n  contextString: generateContextString(byScore, query),\n  \n  // Structured data for custom formatting\n  structured: {\n    query: query,\n    \n    // Main concepts from user query\n    identifiedConcepts: byScore.seeds.map(c => ({\n      name: c.jsonConcept?.prefLabel,\n      definition: c.jsonConcept?.definitions?.[0] || ''No definition available'',\n      synonyms: c.jsonConcept?.altLabels || [],\n      uri: c.jsonConcept?.uri\n    })),\n    \n    // Hierarchical context (narrower/more specific topics)\n    subtopics: {\n      immediate: byScore.primary.slice(0, 15).map(c => ({\n        name: c.jsonConcept?.prefLabel,\n        synonyms: (c.jsonConcept?.altLabels || []).slice(0, 3),\n        definition: c.jsonConcept?.definitions?.[0]\n      })),\n      \n      detailed: byScore.secondary.slice(0, 20).map(c => ({\n        name: c.jsonConcept?.prefLabel,\n        synonyms: (c.jsonConcept?.altLabels || []).slice(0, 2)\n      }))\n    },\n    \n    // Related/sibling topics for context\n    relatedTopics: byScore.related.slice(0, 10).map(c => ({\n      name: c.jsonConcept?.prefLabel,\n      synonyms: (c.jsonConcept?.altLabels || []).slice(0, 2)\n    })),\n    \n    // Semantic boundaries (what''s broader/out of scope)\n    broaderContext: extractBroaderContext(byScore.seeds),\n    \n    // Stats for understanding scope\n    scopeMetrics: {\n      numberOfMainConcepts: byScore.seeds.length,\n      numberOfSubtopics: byScore.primary.length + byScore.secondary.length,\n      hierarchyDepth: byScore.secondary.length > 0 ? 2 : byScore.primary.length > 0 ? 1 : 0,\n      hasRelatedTopics: byScore.related.length > 0\n    }\n  }\n};\n\n// ========================================\n// HELPER FUNCTIONS\n// ========================================\n\nfunction generateContextString(byScore, query) {\n  let context = `Query: \"${query}\"\\n\\n`;\n  \n  // Main concepts\n  if (byScore.seeds.length > 0) {\n    context += `Main Concepts:\\n`;\n    byScore.seeds.forEach(c => {\n      const concept = c.jsonConcept;\n      context += `- ${concept?.prefLabel}`;\n      if (concept?.definitions?.[0]) {\n        context += `: ${concept.definitions[0]}`;\n      }\n      if (concept?.altLabels?.length > 0) {\n        context += ` (Also known as: ${concept.altLabels.slice(0, 3).join('', '')})`;\n      }\n      context += `\\n`;\n    });\n    context += `\\n`;\n  }\n  \n  // Key subtopics\n  if (byScore.primary.length > 0) {\n    context += `Key Subtopics:\\n`;\n    byScore.primary.slice(0, 10).forEach(c => {\n      context += `- ${c.jsonConcept?.prefLabel}`;\n      const alts = c.jsonConcept?.altLabels?.slice(0, 2);\n      if (alts?.length > 0) {\n        context += ` (${alts.join('', '')})`;\n      }\n      context += `\\n`;\n    });\n    context += `\\n`;\n  }\n  \n  // Detailed topics (if not too many)\n  if (byScore.secondary.length > 0 && byScore.secondary.length <= 15) {\n    context += `Detailed Topics:\\n`;\n    byScore.secondary.slice(0, 15).forEach(c => {\n      context += `- ${c.jsonConcept?.prefLabel}\\n`;\n    });\n    context += `\\n`;\n  }\n  \n  // Related topics\n  if (byScore.related.length > 0) {\n    context += `Related Topics: ${byScore.related.slice(0, 8).map(c => c.jsonConcept?.prefLabel).join('', '')}\\n`;\n  }\n  \n  return context;\n}\n\nfunction extractBroaderContext(seeds) {\n  const broaders = new Set();\n  seeds.forEach(seed => {\n    const concept = seed.jsonConcept;\n    if (concept?.broaders) {\n      concept.broaders.forEach(b => broaders.add(b));\n    }\n  });\n  return Array.from(broaders);\n}\n\n// ========================================\n// FINAL OUTPUT\n// ========================================\n\nconst output = {\n  // Metadata\n  metadata: {\n    query: query,\n    language: $(''prepare input data'').first().json.language || ''en'',\n    timestamp: new Date().toISOString(),\n    totalConcepts: expandedConcepts.length,\n    expansionMessage: expansionData.message\n  },\n  \n  // For retrieval systems\n  retrieval: retrievalIndex,\n  \n  // For LLM injection\n  llm: llmContext,\n  \n  // Raw data (if needed for debugging)\n  raw: {\n    seedMetadata: seedData?.seedMetadata || {},\n    allExpandedConcepts: expandedConcepts.map(c => ({\n      score: c.score,\n      uri: c.jsonConcept?.uri,\n      prefLabel: c.jsonConcept?.prefLabel,\n      altLabels: c.jsonConcept?.altLabels || [],\n      definitions: c.jsonConcept?.definitions || []\n    }))\n  }\n};\n\nconsole.log(''✓ Structured output created successfully'');\nconsole.log(''📋 Summary:'', {\n  seedConcepts: byScore.seeds.length,\n  totalURIs: retrievalIndex.allURIs.length,\n  queryExpansionTerms: retrievalIndex.queryExpansionTerms.primary.length,\n  contextStringLength: llmContext.contextString.length\n});\n\nreturn [{ json: output }];"},"alwaysOutputData":true},{"typeVersion":2,"name":"Prepare output data","position":[2096,-208],"id":"25dd692c-02e0-460b-87f0-26bb5ea9bf2a","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {\n  \"conceptExpansion\": $(''Structure expansion results'').first().json,\n  \"executionId\": $executionId\n};\n\n\n\n"}},{"typeVersion":2,"name":"Prepare error data 1","position":[2096,16],"id":"49b2f882-7e27-4842-a143-80505a507b0d","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {\n  \"executionId\": $executionId\n}"}}]', '{"prepare input data":{"main":[[{"node":"Call ''Configuration (sub-workflow)''","index":0,"type":"main"}]]},"Build extraction request":{"main":[[{"node":"Extract concepts from user query","index":0,"type":"main"}]]},"Extract concepts from user query":{"main":[[{"node":"Extract seeds to expand","index":0,"type":"main"}],[{"node":"Prepare error data","index":0,"type":"main"}]]},"Extract seeds to expand":{"main":[[{"node":"If concepts are found","index":0,"type":"main"}]]},"Build expansion request":{"main":[[{"node":"Expand concepts from user query","index":0,"type":"main"}]]},"Prepare output data":{"main":[[{"node":"Insert success data for parallel sync","index":0,"type":"main"}]]},"Prepare error data":{"main":[[{"node":"Insert error data for parallel sync","index":0,"type":"main"}]]},"Prepare JSON list":{"main":[[{"node":"Build expansion request","index":0,"type":"main"}]]},"Expand concepts from user query":{"main":[[{"node":"Structure expansion results","index":0,"type":"main"}],[{"node":"Prepare error data","index":0,"type":"main"}]]},"If concepts are found":{"main":[[{"node":"Prepare JSON list","index":0,"type":"main"}],[{"node":"Prepare error data 1","index":0,"type":"main"}]]},"Call ''Configuration (sub-workflow)''":{"main":[[{"node":"Build extraction request","index":0,"type":"main"}]]},"Prepare error data 1":{"main":[[{"node":"Insert success data for parallel sync","index":0,"type":"main"}]]},"Webhook":{"main":[[{"node":"prepare input data","index":0,"type":"main"}]]},"Structure expansion results":{"main":[[{"node":"Prepare output data","index":0,"type":"main"}]]}}', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:56.482+01', '{"callerPolicy":"workflowsFromSameOwner","errorWorkflow":"Q07I0sRZf6eCtuuF","executionOrder":"v1"}', NULL, '{}', 'd778f2d0-425b-4dad-961c-37af2722f027', 1, 'YL7C5ZQ2kJL7Qvge', '{"instanceId":"982a83c4fa14b8860ea8391b8f766ad449d7431aac64126d0b9fc936877b58be"}', NULL, false, 3, NULL);
