values('9509593a-71ec-40aa-9a48-3c70b97cff06', 'hGEZ9J9UJcOKiqC2qWJoa', 'import', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:58.144+01', '[{"typeVersion":1.1,"name":"Execute workflow","position":[-352,0],"id":"2afe5662-71dc-42fb-8e2a-cd0b3528a0e8","type":"n8n-nodes-base.executeWorkflowTrigger","parameters":{"workflowInputs":{"values":[{"name":"activeFlags","type":"object"},{"name":"executionId"},{"name":"questionId"},{"name":"conversationId"},{"name":"userId"},{"name":"backendSseMessageUrl"}]}}},{"typeVersion":1.1,"name":"Get all rows for the executionId","position":[-144,0],"id":"d3b10bc7-c127-420f-a5ae-6605b7b58c04","type":"n8n-nodes-base.dataTable","parameters":{"matchType":"=anyCondition","dataTableId":{"mode":"list","cachedResultUrl":"/projects/GOpLcxWJaB3HU9kV/datatables/Pw5o6pE18gKIpnNT","__rl":true,"cachedResultName":"PARALLEL_SYNC_DATA","value":"VQol99zJXwRSl6hz"},"filters":{"conditions":[{"keyValue":"={{ $json.executionId }}","keyName":"executionId"}]},"operation":"get"},"alwaysOutputData":true},{"typeVersion":1,"name":"Sticky Note29","position":[224,-48],"id":"fb27a167-ac87-44ad-b74f-dc8f1c426374","type":"n8n-nodes-base.stickyNote","parameters":{"color":5,"width":448,"content":"Explainability message","height":240}},{"typeVersion":2,"name":"Find missing steps","position":[64,0],"id":"35d0904e-7461-4a38-8161-21fe826fb6df","type":"n8n-nodes-base.code","parameters":{"jsCode":"// n8n Code node\n// Returns missing active steps as items: [{ json: { stepTag, message } }]\n\n\nconst stepItems = $(''Get all rows for the executionId'').all().map(item => item.json);\nconst activeFlagsContainer = $(''Execute workflow'').first().json;\n\n// Validate activeFlags input\nconst activeFlags = activeFlagsContainer?.activeFlags || {};\n\n// ------------------------------------------------------------\n// 3) Build a set of existing step names from the first input array\n// ------------------------------------------------------------\nconst existingSteps = new Set(\n  stepItems\n    .map(x => x.step)\n    .filter(step => typeof step === \"string\" && step.length > 0)\n);\n\n// Collect missing active steps\nconst missing = Object.values(activeFlags)\n  .filter(flag => flag?.isActive === true && flag?.stepTag)\n  .filter(flag => !existingSteps.has(flag.stepTag))\n  .map(flag => ({\n    stepName: flag.stepName,\n    message: flag.message || `Step \"${flag.stepTag}\" is missing`,\n  }));\n\nreturn missing.map(item => ({ json: item }));"}},{"typeVersion":2,"name":"Build Ex message - Step has timed out","position":[288,0],"id":"b3ac79c6-aac6-4321-9e5f-1512c56eb434","type":"n8n-nodes-base.code","parameters":{"mode":"runOnceForEachItem","jsCode":"return {     \n  \"questionId\": $(''Execute workflow'').first().json.questionId,\n  \"conversationId\": $(''Execute workflow'').first().json.conversationId,\n  \"userId\": $(''Execute workflow'').first().json.userId,\n  \"messageType\": \"EXPLAINABILITY\",\n  \"payload\":{\n    \"stepName\": $json.stepName,\n    \"description\": $json.message,\n    \"noticeType\": \"ERROR\"\n  }\n};"}},{"typeVersion":4.2,"notesInFlow":false,"name":"Send Ex message - Step has timed out","position":[480,0],"id":"8d8a6780-6c61-4529-a22f-34a0185af3bb","type":"n8n-nodes-base.httpRequest","parameters":{"sendQuery":true,"method":"POST","queryParameters":{"parameters":[{"name":"questionId","value":"={{ $(''Execute workflow'').first().json.questionId }}"}]},"headerParameters":{"parameters":[{"name":"Accept","value":"application/json"}]},"sendBody":true,"options":{},"body":"={{ JSON.stringify( $json ) }}","sendHeaders":true,"contentType":"raw","url":"={{ $(''Execute workflow'').first().json.backendSseMessageUrl }}","rawContentType":"application/json"}}]', '{"Execute workflow":{"main":[[{"node":"Get all rows for the executionId","index":0,"type":"main"}]]},"Find missing steps":{"main":[[{"node":"Build Ex message - Step has timed out","index":0,"type":"main"}]]},"Build Ex message - Step has timed out":{"main":[[{"node":"Send Ex message - Step has timed out","index":0,"type":"main"}]]},"Get all rows for the executionId":{"main":[[{"node":"Find missing steps","index":0,"type":"main"}]]}}', 'initial_publish', false, 'Initially publishing the workflow via the conversation API');
