values('3ac7128c-9d4d-40c4-bf23-24671817b4b0', 'Q07I0sRZf6eCtuuF', 'import', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:58.275+01', '[{"typeVersion":1,"name":"Sticky Note","position":[-592,-256],"id":"eafd17a8-18cc-48da-a1c4-b62abdd23231","type":"n8n-nodes-base.stickyNote","parameters":{"width":1104,"content":"# What to use this workflow for\n## Cathing errors from async workflows - all the optional steps that are executed in parallel from main workflow --> it is making sure the PARALLEL_SYNC_DATA will get a row for the corresponding step in case of an error","height":208}},{"typeVersion":1,"name":"Insert row","position":[448,16],"id":"bf276a83-c2d2-4259-b6ce-f0196f5a7721","type":"n8n-nodes-base.dataTable","parameters":{"columns":{"schema":[{"defaultMatch":false,"removed":false,"displayName":"executionId","display":true,"readOnly":false,"id":"executionId","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"step","display":true,"readOnly":false,"id":"step","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"type","display":true,"readOnly":false,"id":"type","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"value","display":true,"readOnly":false,"id":"value","type":"string","required":false},{"defaultMatch":false,"removed":false,"displayName":"isProcessed","display":true,"readOnly":false,"id":"isProcessed","type":"boolean","required":false}],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":false,"mappingMode":"defineBelow","value":{"executionId":"= {{ $(''Get error workflow data'').first().json.executionId }}","isProcessed":false,"step":"={{ $(''Get error workflow data'').first().json.step}}","type":"error","value":"="}},"dataTableId":{"mode":"list","cachedResultUrl":"/projects/xFJBxfuIaoygFpGG/datatables/MKjbck0nu6xOvBsi","__rl":true,"cachedResultName":"PARALLEL_SYNC_DATA","value":"VQol99zJXwRSl6hz"},"options":{}}},{"typeVersion":2,"name":"Get error workflow data","position":[240,16],"id":"3d5fd170-7b4f-4d1d-b6be-d13917abaeda","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {     \n  \"executionId\": $(''Load failed execution via workflows API'').first().json.data.resultData.runData.Webhook[0].data.main[0][0].json.body.executionId,\n  \"step\":  $(''Load failed execution via workflows API'').first().json.data.resultData.runData[\"prepare input data\"][0].data.main[0][0].json.stepTag\n  \n};"}},{"typeVersion":1,"name":"Error trigger","position":[-576,16],"id":"3a55bdd0-85f5-4060-ab5b-f2c9d6a0da9f","type":"n8n-nodes-base.errorTrigger","parameters":{}},{"typeVersion":1.3,"name":"Configuration","position":[-368,16],"id":"dfa53dfc-ba81-4f82-bc07-0f8646320408","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"schema":[],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":true,"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/n8n/workflow/HJcJwMTssnY79HWw","__rl":true,"cachedResultName":"Configuration","value":"HJcJwMTssnY79HWw"}}},{"typeVersion":1,"name":"Get worfklows API key","position":[-160,16],"id":"3aae3790-e057-4cdd-a03a-ac4c1198cf7e","type":"n8n-nodes-base.dataTable","parameters":{"dataTableId":{"mode":"list","cachedResultUrl":"/projects/9M6Oa5bE1OSRWGNB/datatables/reqr3BTx9DmGpZ8N","__rl":true,"cachedResultName":"API_KEYS","value":"l7ntmWyu1cIic61W"},"filters":{"conditions":[{"keyValue":"N8N","keyName":"type"}]},"operation":"get"}},{"typeVersion":4.2,"name":"Load failed execution via workflows API","position":[32,16],"id":"3224b339-d9c4-4eec-918d-675795f3fcdd","type":"n8n-nodes-base.httpRequest","parameters":{"headerParameters":{"parameters":[{"name":"X-N8N-API-KEY","value":"={{ $json.value }}"}]},"options":{},"sendHeaders":true,"url":"={{ $(''Configuration'').item.json.internalN8nUrl }}/api/v1/executions/{{ $(''Error trigger'').item.json.execution.id }}?includeData=true"}}]', '{"Load failed execution via workflows API":{"main":[[{"node":"Get error workflow data","index":0,"type":"main"}]]},"Configuration":{"main":[[{"node":"Get worfklows API key","index":0,"type":"main"}]]},"Get error workflow data":{"main":[[{"node":"Insert row","index":0,"type":"main"}]]},"Error trigger":{"main":[[{"node":"Configuration","index":0,"type":"main"}]]},"Get worfklows API key":{"main":[[{"node":"Load failed execution via workflows API","index":0,"type":"main"}]]}}', 'initial_publish', false, 'Initially publishing the workflow via the conversation API');
