se,"canBeUsedToMatch":true,"displayName":"maxNumberTokens","display":true,"id":"maxNumberTokens","type":"number","required":false},{"defaultMatch":false,"canBeUsedToMatch":true,"displayName":"samplingTemperature","display":true,"id":"samplingTemperature","type":"number","required":false}],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":true,"mappingMode":"defineBelow","value":{"systemMessage":"={{ $json.systemMessageTemplate }}","structuredOutputParserJsonSchema":"={{ $json.structuredOutputParserJsonSchema }}","maxNumberTokens":2000,"samplingTemperature":0,"prompt":"Given the following answer to a question, generate relevant follow-up questions that would help the user explore the topic in more depth.","secondaryLLMModel":"={{ $(''Call \\''Configuration (sub-workflow)\\'''').item.json.secondaryLLMModel }}","primaryLLMModel":"={{ $(''Call \\''Configuration (sub-workflow)\\'''').item.json.primaryLLMModel }}"}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/n8n/workflow/icEaxOxBisUj5nUb","__rl":true,"cachedResultName":"LLM call","value":"icEaxOxBisUj5nUb"}}},{"typeVersion":2,"name":"Prepare data for LLM call","position":[-272,-16],"id":"ccac0de9-b43e-45a3-a973-fb3a17147518","type":"n8n-nodes-base.code","parameters":{"jsCode":"var systemMessageTemplate = `Given the following answer to a question, generate relevant follow-up questions that would help the user explore the topic in more depth.\n\nQuestion:\n{{ Question }}\n\nAnswer:\n{{ Answer }}\n\nPlease generate 3-5 follow-up questions that:\n1. Are specific and focused on different aspects of the answer\n2. Help explore technical details or implications\n3. Consider different perspectives or approaches\n4. Address potential gaps or areas for further exploration\n\nFor each question, provide:\n- The question itself\n- Reasoning for why this question is relevant\n- Key topics or concepts the question addresses\n\nProvide your response in JSON format with the following structure:\n{\n    \"follow_up_questions\": [\n        {\n            \"question\": \"The follow-up question\",\n            \"reasoning\": \"Why this question is relevant\",\n            \"topics\": [\"List\", \"of\", \"relevant\", \"topics\"]\n        }\n    ]\n}\n\nFocus on technical accuracy and professional communication. Return ONLY the JSON object, with no additional text or explanation.`\n\nconst question = $(''prepare input data'').first().json.question;\nconst answer = $(''prepare input data'').first().json.answer;\n\nsystemMessageTemplate = systemMessageTemplate.replace(''{{ Question }}'', question);\nsystemMessageTemplate = systemMessageTemplate.replace(''{{ Answer }}'', answer);\n\nconst structuredOutputParserJsonSchema = {\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"type\": \"object\",\n  \"properties\": {\n    \"follow_up_questions\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"question\": {\n            \"type\": \"string\"\n          },\n          \"reasoning\": {\n            \"type\": \"string\"\n          },\n          \"topics\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"string\"\n            }\n          }\n        },\n        \"required\": [\n          \"question\",\n          \"reasoning\",\n          \"topics\"\n        ],\n          \"additionalProperties\": false\n      }\n    }\n  },\n  \"required\": [\n    \"follow_up_questions\"\n  ],\n    \"additionalProperties\": false\n}\n\nreturn { \"systemMessageTemplate\" : systemMessageTemplate,\n         \"structuredOutputParserJsonSchema\" : structuredOutputParserJsonSchema\n       }\n"}}]', '{"prepare input data":{"main":[[{"node":"Call ''Configuration (sub-workflow)''","index":0,"type":"main"}]]},"Call ''Configuration (sub-workflow)''":{"main":[[{"node":"Prepare data for LLM call","index":0,"type":"main"}]]},"Prepare error data":{"main":[[{"node":"Insert error data for parallel sync","index":0,"type":"main"}]]},"LLM call":{"main":[[{"node":"Prepare response","index":0,"type":"main"}],[{"node":"Prepare error data","index":0,"type":"main"}]]},"Prepare response":{"main":[[{"node":"Insert success data for parallel sync","index":0,"type":"main"}]]},"Webhook":{"main":[[{"node":"prepare input data","index":0,"type":"main"}]]},"Prepare data for LLM call":{"main":[[{"node":"LLM call","index":0,"type":"main"}]]}}', 'initial_publish', false, 'Initially publishing the workflow via the conversation API');
