values('04f83218-6481-4cea-b97b-89580eae231d', '6GvPTrXQOujasWoA', 'import', '2026-03-27 09:43:56.482+01', '2026-03-27 09:43:59.886+01', '[{"typeVersion":1,"name":"Sticky Note2","position":[-1568,-160],"id":"392850cf-701a-4d7b-b239-a2b3543f23f2","type":"n8n-nodes-base.stickyNote","parameters":{"width":416,"content":"## Input\n- **question**: string - The question asked by the user\n- **answer**: string - The produced answer to the question asked","height":128}},{"typeVersion":1,"name":"Sticky Note3","position":[-96,-336],"id":"aa9ce120-7f4b-4952-a97a-3c6f676de86e","type":"n8n-nodes-base.stickyNote","parameters":{"width":432,"content":"## Output\n- **execution_id**: string - The ID of the current execution\n- **result**: object - All details about the guardrail check\n-- **result**: number - A quality identifier (1-10) --> the higher the number the better the quality of the answer. Based on this number (e.g. 9) the guardrail check either passes or fails.\n-- **severity**: string - The level of risk, e.g. \"low\"\n-- **description** - string - A human-readable summary of the quality and threat potential of the generated answer","height":256}},{"typeVersion":1.3,"name":"Call ''Configuration (sub-workflow)''","position":[-704,-16],"id":"3143c486-d18e-4be2-bf50-4b6399aa177f","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/workflow/HJcJwMTssnY79HWw","__rl":true,"cachedResultName":"Configuration (sub-workflow)","value":"HJcJwMTssnY79HWw"}}},{"typeVersion":2.1,"webhookId":"944df46b-cfa1-499a-afb5-97289bede068","name":"Webhook","position":[-1248,-16],"id":"68a9d70f-2870-4000-a2f5-36b135dc1435","type":"n8n-nodes-base.webhook","parameters":{"path":"internal/output-guardrails","options":{},"httpMethod":"POST"}},{"typeVersion":2,"name":"prepare input data","position":[-992,-16],"id":"650603ac-b38d-4888-9762-4b0ffa188ec9","type":"n8n-nodes-base.code","param