values('7cb58b00-b450-4be8-b8e0-bd2d3ed35b73', 'bMtpMHfiZXW5GJBc', 'import', '2026-03-27 09:43:56.482+01', '2026-03-27 09:44:00.568+01', '[{"typeVersion":1.1,"name":"Start","id":"ef058c4d-d581-49ba-80a1-e292dae0d724","position":[-736,400],"type":"n8n-nodes-base.executeWorkflowTrigger","parameters":{"workflowInputs":{"values":[{"name":"execution_id"}]}}},{"typeVersion":2,"name":"Code","position":[736,384],"id":"ebc76e66-56cd-4170-a398-c945dda53642","type":"n8n-nodes-base.code","parameters":{"jsCode":"return [\n  {\n    tokens: $input.first().json.totals\n    //,trace: JSON.stringify($(''GraphRAG workflow engine'').all())\n  }\n]"}},{"typeVersion":2,"name":"Check parameters","position":[-544,400],"id":"e1b575d3-7449-44b3-8507-13b238db3959","type":"n8n-nodes-base.code","parameters":{"jsCode":"var exec_id = \"0\"\nif ($input === null || $input.first()===null || $input.first().json.execution_id === null){\n  exec_id = \"0\"\n}else{\n   exec_id = $input.first().json.execution_id.toString()\n}\n\nreturn {\n  execution_id: exec_id\n}"}},{"typeVersion":2.2,"name":"If executionId is good","position":[-336,400],"id":"d7a4a2e0-30ae-4971-b1e9-80b8e3d355d1","type":"n8n-nodes-base.if","parameters":{"options":{},"conditions":{"combinator":"and","options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"leftValue":"={{ $json.execution_id }}","rightValue":"0","id":"5f04b469-2ba0-4e26-84eb-ab0df95528b7","operator":{"type":"string","operation":"notEquals"}}]}}},{"typeVersion":2,"name":"JavaScript code","position":[-64,592],"id":"718f9b86-7e51-47d3-b10c-ffcfef1df086","type":"n8n-nodes-base.code","parameters":{"jsCode":"var totals = {\n\tcompletionTokens: 0,\n\tpromptTokens: 0,\n\ttotalTokens: 0,\n}\n\nreturn [{ totals }];"}},{"typeVersion":2,"name":"Aggregate tokens","id":"874fe5a9-c59d-4edd-bc7a-ce746301718c","position":[512,384],"type":"n8n-nodes-base.code","parameters":{"jsCode":"const input = $input.all();\nconst data = input[0].json;\n\nconst nodes = data.workflowData?.nodes ?? [];\n\nconst totals = {\n\tcompletionTokens: 0,\n\tpromptTokens: 0,\n\ttotalTokens: 0,\n};\n\nconst models = new Set();\nconst detailedUsages = [];\n\nfunction accumulate(usage) {\n\tif (\n\t\ttypeof usage.completionTokens === ''number'' &&\n\t\ttypeof usage.promptTokens === ''number'' &&\n\t\ttypeof usage.totalTokens === ''number''\n\t) {\n\t\ttotals.completionTokens += usage.completionTokens;\n\t\ttotals.promptTokens += usage.promptTokens;\n\t\ttotals.totalTokens += usage.totalTokens;\n\n\t\tdetailedUsages.push({\n\t\t\tusage: { ...usage },\n\t\t});\n\t}\n}\n\nfunction findTokenUsageRecursively(obj) {\n\tif (typeof obj !== ''object'' || obj === null) return;\n\n\tif (\n\t\ttypeof obj.completionTokens === ''number'' &&\n\t\ttypeof obj.promptTokens === ''number'' &&\n\t\ttypeof obj.totalTokens === ''number''\n\t) {\n\t\taccumulate(obj);\n\t\treturn;\n\t}\n}\n\nfunction processExecution(exec) {\n\t//const node = nodes.find((n) => console.log(n.name));\n\t//const model = node?.parameters?.modelName || node.parameters?.model || node.parameters?.name;\n\tfindTokenUsageRecursively(exec);\n}\n\nfunction jsonPath(obj, expr, arg) {\n   var P = {\n      resultType: arg && arg.resultType || \"VALUE\",\n      result: [],\n      normalize: function(expr) {\n         var subx = [];\n         return expr.replace(/[\\[''](\\??\\(.*?\\))[\\]'']/g, function($0,$1){return \"[#\"+(subx.push($1)-1)+\"]\";})\n                    .replace(/''?\\.''?|\\[''?/g, \";\")\n                    .replace(/;;;|;;/g, \";..;\")\n                    .replace(/;$|''?\\]|''$/g, \"\")\n                    .replace(/#([0-9]+)/g, function($0,$1){return subx[$1];});\n      },\n      asPath: function(path) {\n         var x = path.split(\";\"), p = \"$\";\n         for (var i=1,n=x.length; i<n; i++)\n            p += /^[0-9*]+$/.test(x[i]) ? (\"[\"+x[i]+\"]\") : (\"[''\"+x[i]+\"'']\");\n         return p;\n      },\n      store: function(p, v) {\n         if (p) P.result[P.result.length] = P.resultType == \"PATH\" ? P.asPath(p) : v;\n         return !!p;\n      },\n      trace: function(expr, val, path) {\n         if (expr) {\n            var x = expr.split(\";\"), loc = x.shift();\n            x = x.join(\";\");\n            if (val && val.hasOwnProperty(loc))\n               P.trace(x, val[loc], path + \";\" + loc);\n            else if (loc === \"*\")\n               P.walk(loc, x, val, path, function(m,l,x,v,p) { P.trace(m+\";\"+x,v,p); });\n            else if (loc === \"..\") {\n               P.trace(x, val, path);\n               P.walk(loc, x, val, path, function(m,l,x,v,p) { typeof v[m] === \"object\" && P.trace(\"..;\"+x,v[m],p+\";\"+m); });\n            }\n            else if (/,/.test(loc)) { // [name1,name2,...]\n               for (var s=loc.split(/''?,''?/),i=0,n=s.length; i<n; i++)\n                  P.trace(s[i]+\";\"+x, val, path);\n            }\n            else if (/^\\(.*?\\)$/.test(loc)) // [(expr)]\n               P.trace(P.eval(loc, val, path.substr(path.lastIndexOf(\";\")+1))+\";\"+x, val, path);\n            else if (/^\\?\\(.*?\\)$/.test(loc)) // [?(expr)]\n               P.walk(loc, x, val, path, function(m,l,x,v,p) { if (P.eval(l.replace(/^\\?\\((.*?)\\)$/,\"$1\"),v[m],m)) P.trace(m+\";\"+x,v,p); });\n            else if (/^(-?[0-9]*):(-?[0-9]*):?([0-9]*)$/.test(loc)) // [start:end:step]  phyton slice syntax\n               P.slice(loc, x, val, path);\n         }\n         else\n            P.store(path, val);\n      },\n      walk: function(loc, expr, val, path, f) {\n         if (val instanceof Array) {\n            for (var i=0,n=val.length; i<n; i++)\n               if (i in val)\n                  f(i,loc,expr,val,path);\n         }\n         else if (typeof val === \"object\") {\n            for (var m in val)\n               if (val.hasOwnProperty(m))\n                  f(m,loc,expr,val,path);\n         }\n      },\n      slice: function(loc, expr, val, path) {\n         if (val instanceof Array) {\n            var len=val.length, start=0, end=len, step=1;\n            loc.replace(/^(-?[0-9]*):(-?[0-9]*):?(-?[0-9]*)$/g, function($0,$1,$2,$3){start=parseInt($1||start);end=parseInt($2||end);step=parseInt($3||step);});\n            start = (start < 0) ? Math.max(0,start+len) : Math.min(len,start);\n            end   = (end < 0)   ? Math.max(0,end+len)   : Math.min(len,end);\n            for (var i=start; i<end; i+=step)\n               P.trace(i+\";\"+expr, val, path);\n         }\n      },\n      eval: function(x, _v, _vname) {\n         try { return $ && _v && eval(x.replace(/@/g, \"_v\")); }\n         catch(e) { throw new SyntaxError(\"jsonPath: \" + e.message + \": \" + x.replace(/@/g, \"_v\").replace(/\\^/g, \"_a\")); }\n      }\n   };\n\n   var $ = obj;\n   if (expr && obj && (P.resultType == \"VALUE\" || P.resultType == \"PATH\")) {\n      P.trace(P.normalize(expr).replace(/^\\$;/,\"\"), obj, \"$\");\n      return P.result.length ? P.result : false;\n   }\n} \n\n\n//find all nodes that have\nvar results = jsonPath(data.data, \"*...ai_languageModel..\")\n\nfor (var res of results) {\n  if (typeof res === ''object'' && res.tokenUsageEstimate) {\n\t\tconsole.log(\"Processing:\"+JSON.stringify(res))\n        processExecution(res.tokenUsageEstimate)\n\t}\n}\n\n// Procesar cada nodo indicado\n\nconst executions = data.data?.resultData?.runData;\n\n//if (Array.isArray(executions)) {\n//\texecutions.forEach((exec) => processExecution(exec));\n//} else if (typeof executions === ''object'') {\n//\tprocessExecution(executions);\n//}\n\nreturn [\n\t{\n\t  totals,\n\t  model: models\n\t},\n];\n"}},{"typeVersion":1.3,"name":"Configuration","position":[-96,384],"id":"96b716d5-3ea9-49a0-834d-0a5571e8099b","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"schema":[],"attemptToConvertTypes":false,"matchingColumns":[],"convertFieldsToString":true,"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl"