.json.executionId }}","isProcessed":false,"step":"={{ $(''prepare input data'').first().json.stepTag}}","type":"error","value":"={{ JSON.stringify($json) }}"}},"dataTableId":{"mode":"list","cachedResultUrl":"/projects/xFJBxfuIaoygFpGG/datatables/MKjbck0nu6xOvBsi","__rl":true,"cachedResultName":"PARALLEL_SYNC_DATA","value":"VQol99zJXwRSl6hz"},"options":{}}},{"typeVersion":1.3,"name":"Call ''Configuration (sub-workflow)''","position":[-16,0],"id":"49a5d649-3ff4-47de-b6fb-9f2298b8bac8","type":"n8n-nodes-base.executeWorkflow","parameters":{"workflowInputs":{"mappingMode":"defineBelow","value":{}},"options":{},"workflowId":{"mode":"list","cachedResultUrl":"/workflow/HJcJwMTssnY79HWw","__rl":true,"cachedResultName":"Configuration (sub-workflow)","value":"HJcJwMTssnY79HWw"}}},{"typeVersion":2,"onError":"continueErrorOutput","name":"Prepare response","position":[1136,0],"id":"4f8e1a73-161f-44a2-bf71-390c15f227e1","type":"n8n-nodes-base.code","parameters":{"jsCode":"// Use the correct mapping based on the vector store type.\nconst vectorStorePreset = $(''Call \\''Configuration (sub-workflow)\\'''').first().json.vectorStorePreset;\nlet presetMapping = {};\nif (vectorStorePreset !== \"custom\") {\n  presetMapping = $(''Vector Store mapping presets'').first().json[vectorStorePreset];\n}\nelse {\n  presetMapping = $(''Call \\''Configuration (sub-workflow)\\'''').first().json.vectorStoreCustomMappins;\n}\n\nconst docs = []\n\n/**\n * Get a value of one of the vector store result using the preset mappings.\n @param itemJson The JSON of the results item to get the value for\n @param mapping The mapping to use\n @returns The requested value of the results item\n */\nconst getMappedValue = function(itemJson, mapping) {\n  const mappingArray = mapping.split(\".\");\n  for (const key of mappingArray) {\n    if (itemJson.hasOwnProperty(key)) {\n      itemJson = itemJson[key];\n    }\n    else {\n      return null;\n    }\n  }\n  return itemJson;\n}\n\n/**\n * Exclude (nullifies) certain properties from the passed-through metadata.\n * @param itemJson The JSON of the results item containing metadata to exclude properties from\n * @returns The metadata object with nullified properties\n */\nconst buildPassthroughMetadata = function(itemJson) {\n  const passthroughMetadata = $(''Call \\''Configuration (sub-workflow)\\'''').first().json.vectorStoreMetadataPassthrough;\n\n  if (passthroughMetadata) {\n    const metadataKey = presetMapping.source.split(\".\")[0];\n    if (itemJson.hasOwnProperty(metadataKey)) {\n      const metadata = itemJson[metadataKey];\n      const excludeProperties = $(''Call \\''Configuration (sub-workflow)\\'''').first().json.vectorStoreMetadataExclude;\n      for (const property of excludeProperties) {\n        if (metadata.hasOwnProperty(property)) {\n          metadata[property] = null;\n        }\n      }\n      return metadata;\n    }\n  }\n  \n  return null;\n}\n\n// Build an array of result documents, independent of the original mapping of the vector store.\nfor (const item of $input.all()) {\n  const itemJson = item.json;\n  const source = getMappedValue(itemJson, presetMapping.source);\n  const payload = getMappedValue(itemJson, presetMapping.payload);\n  if (source === null || payload === null) {\n    throw new Error(\"Mandatory vector store results property is either not available or null\");\n  }\n  \n  const doc = {\n    \"id\": getMappedValue(itemJson, presetMapping.id),\n    \"source\": source,\n    \"score\": getMappedValue(itemJson, presetMapping.score),\n    \"payload\": payload,\n    \"metadata\": buildPassthroughMetadata(itemJson)\n  }\n  //swconsole.log(doc)\n  docs.push(doc);\n}\n\nreturn {\n  \"vector_hits\":  docs\n};"},"alwaysOutputData":true},{"typeVersion":2,"name":"Prepare error data","position":[1344,240],"id":"7b14dcf8-4b48-4f86-9010-55797a3d216d","type":"n8n-nodes-base.code","parameters":{"jsCode":"return {\n  \"executionId\": $executionId\n}"}},{"typeVersion":2,"name":"Prepare output data","positi